// <auto-imports> — generated by wire.mjs, do not edit by hand
import { getOwnedActor, tokenDocumentsForActorOnScene } from "./actors.js";
import { CHARACTER_IMAGE_MAX_LONG_SIDE, MODULE_ID, OFFLINE_OPERATION, SOCKET_NAME } from "./constants.js";
import { uploadActorImage } from "./map.js";
import { actorItemCreateCustom } from "./offline.js";
import { routeAssetPath, routeDocumentImg } from "./sheet.js";
// </auto-imports>
// Actor/item images, portrait/token, offline labels — extracted from mobile-bridge.js.

export async function actorPortraitSet(user, actorId, payload) {
  if (!payload?.imageBase64) throw new Error("imageBase64 is required");
  const actor = getOwnedActor(user, actorId);
  // A portrait is open to any player who owns the actor: making a character is
  // the first thing a new player does, and asking a GM to grant FILES_UPLOAD
  // first defeats it. What lands on disk is re-encoded through a canvas, given
  // a random name and forced to .png/.jpg, so it can only ever be an image.
  const imgPath = await uploadActorImage(
    user, actor, payload.imageBase64, payload.mimeType,
    { requirePermission: false, maxLongSide: CHARACTER_IMAGE_MAX_LONG_SIDE }
  );
  await actor.update({ img: imgPath });
  // Unlinked tokens keep their own texture; only refresh the prototype so new
  // tokens inherit the portrait without rewriting what is already on the map.
  if (payload?.applyToPrototypeToken === true) {
    await actor.update({ "prototypeToken.texture.src": imgPath });
  }
  return { accepted: true, actorId: actor.id, img: routeAssetPath(imgPath) };
}

/**
 * Replaces the art on the actor's prototype token.
 *
 * Separate from the portrait: the sheet picture and the thing on the map are
 * different pictures for most characters, and a token wants the framing that
 * reads at one grid square.
 */
export async function actorTokenImageSet(user, actorId, payload) {
  if (!payload?.imageBase64) throw new Error("imageBase64 is required");
  const actor = getOwnedActor(user, actorId);
  const imgPath = await uploadActorImage(
    user, actor, payload.imageBase64, payload.mimeType,
    { requirePermission: false, maxLongSide: CHARACTER_IMAGE_MAX_LONG_SIDE }
  );
  await actor.update({ "prototypeToken.texture.src": imgPath });
  return { accepted: true, actorId: actor.id, img: routeAssetPath(imgPath) };
}

/**
 * Create a custom loot item on the actor without GM approval. Any player who
 * owns the actor may add loot — it has no combat stats, only descriptive fields.
 */
export async function actorItemCreateLoot(user, actorId, payload) {
  const name = String(payload?.name ?? "").trim();
  if (!name) throw new Error("Loot name is required");
  const description = String(payload?.description ?? payload?.summary ?? "").trim();
  let imgPath = null;
  if (payload?.imageBase64) {
    imgPath = await uploadActorImage(user, getOwnedActor(user, actorId), payload.imageBase64, payload.mimeType);
  }
  const change = {
    itemType: "loot",
    isSpell: false,
    quantity: 1,
    name,
    summary: description,
    chatDescription: String(payload?.chatDescription ?? "").trim(),
    weight: payload?.weight,
    price: payload?.price,
    priceDenomination: payload?.priceDenomination,
    img: imgPath
  };
  return actorItemCreateCustom(user, actorId, change);
}

/**
 * Comparable form of an asset path. `getRoute` prepends the world's route
 * prefix and a leading slash, so the same file has two spellings depending on
 * which side of the socket you are looking from.
 */
export function assetKey(raw) {
  const text = String(raw ?? "").trim();
  if (!text) return "";
  if (/^(https?:)?\/\//i.test(text) || text.startsWith("data:")) return text;
  const prefix = String(globalThis.ROUTE_PREFIX ?? game?.data?.options?.routePrefix ?? "").trim();
  let path = text.replace(/^\/+/, "");
  if (prefix) {
    const clean = prefix.replace(/^\/+|\/+$/g, "");
    if (clean && path.startsWith(`${clean}/`)) path = path.slice(clean.length + 1);
  }
  return decodeURIComponent(path);
}

/**
 * Art the requesting user may legitimately put on everyone's screen: their own
 * actor's portrait, token and item images. Sharing takes over every client's
 * view, so the source is whitelisted rather than trusted from the payload.
 */
export function shareableActorImages(actor) {
  const allowed = new Set();
  const add = (raw) => {
    if (!raw || typeof raw !== "string") return;
    // Both forms: the client is handed routed paths ("/icons/x.webp") and hands
    // them straight back, while documents store them raw ("icons/x.webp").
    allowed.add(assetKey(raw));
  };
  add(actor?.img);
  add(actor?.prototypeToken?.texture?.src);
  for (const td of tokenDocumentsForActorOnScene(actor, canvas?.scene)) {
    add(td.texture?.src);
  }
  for (const item of actor?.items ?? []) add(item.img);
  return allowed;
}

/**
 * Foundry's "Show to Players": pops the image on every connected client.
 *
 * The core API moved between versions, so both shapes are attempted. Mobile
 * clients are not Foundry clients and would see nothing, so they get their own
 * push and render it themselves.
 */
export async function imageShowToPlayers(user, actorId, payload) {
  const actor = getOwnedActor(user, actorId);
  const src = String(payload?.src ?? "").trim();
  if (!src) throw new Error("src is required");
  if (!shareableActorImages(actor).has(assetKey(src))) {
    throw new Error("Only art from your own character can be shared");
  }
  const title = String(payload?.title ?? actor.name ?? "").trim();
  const routed = routeAssetPath(src);

  const PopoutClass = foundry.applications?.apps?.ImagePopout ?? globalThis.ImagePopout;
  try {
    if (typeof PopoutClass?.shareImage === "function") {
      await PopoutClass.shareImage({ src: routed, image: routed, title, uuid: actor.uuid });
    } else if (PopoutClass) {
      const popout = new PopoutClass({ src: routed, uuid: actor.uuid, window: { title } });
      if (typeof popout.shareImage === "function") await popout.shareImage();
    }
  } catch (err) {
    // A desktop-side failure must not stop the mobile push: at a phone-heavy
    // table that is the half that matters.
    console.warn(`[${MODULE_ID}] ImagePopout share failed`, err);
  }

  if (game.socket) {
    for (const target of game.users.filter((u) => u.active && u.id !== user.id)) {
      game.socket.emit(SOCKET_NAME, {
        event: "image.share",
        payload: { src: routed, title, fromUserName: user.name ?? "" },
        meta: { targetUserId: target.id }
      });
    }
  }
  return { accepted: true, src: routed, title };
}

/**
 * Edit a loot item the player owns: name, description, weight, price.
 *
 * Loot only, and no GM approval — same rationale as creating it. Loot carries
 * no combat stats, so nothing here changes what the character can do. Blank
 * fields clear the value rather than being ignored, or a price entered by
 * mistake could never be removed from the phone.
 */
export async function actorItemUpdateLoot(user, actorId, itemId, payload) {
  if (!itemId || typeof itemId !== "string") throw new Error("itemId is required");
  const actor = getOwnedActor(user, actorId);
  const item = actor.items.get(itemId);
  if (!item) throw new Error(`Item not found on actor: ${itemId}`);
  if (item.type !== "loot") throw new Error("Only loot items can be edited from mobile");

  const name = String(payload?.name ?? "").trim();
  if (!name) throw new Error("Loot name is required");

  const update = {
    name,
    "system.description.value": String(payload?.description ?? ""),
    "system.description.chat": String(payload?.chatDescription ?? "")
  };

  const weight = Number(payload?.weight);
  update["system.weight.value"] = Number.isFinite(weight) && weight >= 0 ? weight : 0;
  update["system.weight.units"] = item.system?.weight?.units ?? "lb";

  const price = Number(payload?.price);
  update["system.price.value"] = Number.isFinite(price) && price >= 0 ? price : 0;
  update["system.price.denomination"] =
    String(payload?.priceDenomination ?? item.system?.price?.denomination ?? "gp").trim() || "gp";

  await item.update(update);
  return {
    accepted: true,
    itemId: item.id,
    name: item.name,
    img: routeDocumentImg(item)
  };
}

/**
 * Replace an owned item's portrait. Uploads to Data/assets/ like createLoot.
 * Any actor owner may update loot icons without GM approval.
 */
export async function actorItemSetImage(user, actorId, itemId, payload) {
  if (!itemId || typeof itemId !== "string") throw new Error("itemId is required");
  if (!payload?.imageBase64) throw new Error("imageBase64 is required");
  const actor = getOwnedActor(user, actorId);
  const item = actor.items.get(itemId);
  if (!item) throw new Error(`Item not found on actor: ${itemId}`);
  // Any owned item, not just loot: art for a weapon or a spell is the same
  // act, and FILES_UPLOAD is what decides whether the player may do it.
  const imgPath = await uploadActorImage(user, actor, payload.imageBase64, payload.mimeType);
  await item.update({ img: imgPath });
  return {
    accepted: true,
    itemId: item.id,
    name: item.name,
    img: routeDocumentImg(item)
  };
}

export function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

/**
 * Whisper one line to every GM in chat. The full request is also written to the
 * character's approval-log journal (see writeApprovalLogEntry), so chat + journal
 * are the whole record. No toast popups: a permanent ui.notifications warning on
 * the primary tab was the intrusive thing to drop here.
 */
export async function notifyGmsOfflineBatchSubmitted({ userName, actorName, pendingLeft, grantFailures = 0 }) {
  const who = String(userName ?? "Player");
  const actor = String(actorName ?? "character");
  let text;
  if (pendingLeft) {
    text = grantFailures > 0
      ? `Foundry Mobile: ${who} submitted changes for ${actor} — GM approval needed (${grantFailures} grant failed)`
      : `Foundry Mobile: ${who} submitted changes for ${actor} — GM approval needed`;
  } else {
    text = `Foundry Mobile: ${who} submitted changes for ${actor} (auto-applied)`;
  }

  const gmIds = game.users.filter((u) => u.isGM).map((u) => u.id);
  if (gmIds.length && typeof ChatMessage?.create === "function") {
    await ChatMessage.create({
      content: `<p><strong>Bag of Worlds</strong></p><p>${escapeHtml(text)}</p>`,
      whisper: gmIds,
      speaker: { alias: "Bag of Worlds" }
    });
  }
}

// Kept as a no-op: offline submissions no longer broadcast toast popups to other
// GM tabs — the whispered chat message already reaches every GM, and the request
// is logged to the character's approval journal. Left in place so a stray message
// from an older bridge tab mid-rollout is harmlessly ignored.
export function handleOfflineApprovalsNotify() {}

export function offlineOperationLabel(change) {
  if (change.operation === OFFLINE_OPERATION.ITEM_CREATE_TEXT && change.itemId) {
    return `Stack +${change.quantity}: ${change.name || change.itemId}`;
  }
  if (change.operation === OFFLINE_OPERATION.ITEM_CREATE_TEXT) return change.isSpell ? "Add spell" : "Add item";
  if (change.operation === OFFLINE_OPERATION.ITEM_CREATE_FROM_UUID) {
    return change.isSpell ? `Add spell (UUID): ${change.name || change.uuid}` : `Add item (UUID): ${change.name || change.uuid}`;
  }
  if (change.operation === OFFLINE_OPERATION.ITEM_DELETE) return "Delete item";
  if (change.operation === OFFLINE_OPERATION.ITEM_QUANTITY) return `Set quantity to ${change.quantity}`;
  if (change.operation === OFFLINE_OPERATION.CURRENCY_SET) return `Set currency ${change.itemId ?? "?"} to ${change.quantity}`;
  if (change.operation === OFFLINE_OPERATION.CLASS_LEVEL_CHANGE) {
    const bits = [`Set class level to ${change.quantity}: ${change.name || change.itemId || "?"}`];
    if (change.featName || change.featUuid) bits.push(`feat=${change.featName || change.featUuid}`);
    if (change.subclassName || change.subclassUuid) {
      bits.push(`subclass=${change.subclassName || change.subclassUuid}`);
    }
    if (change.asiAssignments) bits.push(`ASI=${change.asiAssignments}`);
    return bits.join("; ");
  }
  if (change.operation === OFFLINE_OPERATION.ABILITY_SET) {
    return `Set ability ${change.itemId ?? "?"} to ${change.quantity}`;
  }
  // Never shown in the approval dialog (biography rows resolve at submit), but this
  // label also feeds the grant log.
  if (change.operation === OFFLINE_OPERATION.BIOGRAPHY_SET) {
    const preview = String(change.textValue ?? "").replace(/\s+/g, " ").trim().slice(0, 60);
    return `Set biography ${change.itemId ?? "?"}: ${preview || "(empty)"}`;
  }
  if (change.operation === OFFLINE_OPERATION.SHEET_OVERRIDE) {
    const v = change.summary?.trim() || change.quantity;
    return `Sheet override ${change.itemId ?? "?"}: ${change.name || v}`;
  }
  return change.operation;
}
